// src/utils/jwt.ts
import jwt from "jsonwebtoken";
var createToken = (payload, secret, expiresIn) => {
  const token = jwt.sign(payload, secret, { expiresIn });
  return token;
};
var verifyToken = (token, secret) => {
  try {
    const verifiedToken = jwt.verify(token, secret);
    return {
      success: true,
      data: verifiedToken
    };
  } catch (error) {
    console.log("Token verification failed", error);
    return {
      success: false,
      error: error.message
    };
  }
};
var jwtUtils = {
  createToken,
  verifyToken
};

// src/middleware/auth.ts
var auth = (...requiredRoles) => {
  return catchAsync(async (req, res, next) => {
    const token = req.cookies.accessToken ? req.cookies.accessToken : req.headers.authorization?.startsWith("Bearer") ? req.headers.authorization.split(" ")[1] : req.headers.authorization;
    if (!token) {
      throw new Error("You are not authorized. Please log in.");
    }
    const verifiedToken = jwtUtils.verifyToken(token, config_default.jwt_access_secret);
    if (!verifiedToken.success) {
      throw new Error(verifiedToken.error);
    }
    const { id, name, email, role } = verifiedToken.data;
    if (requiredRoles.length && !requiredRoles.includes(role)) {
      sendResponse(res, {
        success: false,
        statusCode: httpStatus2.FORBIDDEN,
        message: "Forbidden: You do not have permission to access this resource."
      });
    }
    const user = await prisma.user.findUniqueOrThrow({
      where: {
        id,
        name,
        email,
        role
      }
    });
    if (!user) {
      throw new Error("User not found. Please login again.");
    }
    if (user.accountStatus === "BANNED") {
      throw new Error("Your account has been banned. Please contact to the support team.");
    }
    req.user = {
      id,
      name,
      email,
      role
    };
    next();
  });
};

