// src/modules/payment/payment.controller.ts
var createPayment = catchAsync(async (req, res, next) => {
  const { rentalRequestId } = req.body;
  const tenantId = req.user?.id;
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  if (!tenantId) {
    throw new Error("Tenant id is not found.");
  }
  if (!rentalRequestId) {
    throw new Error("Rental request id is required");
  }
  if (typeof rentalRequestId !== "string" || !uuidRegex.test(rentalRequestId)) {
    throw new Error("Rental request id must be a string and should be given in a valid format");
  }
  const result = await paymentServices.createPaymentIntoDB(tenantId, rentalRequestId);
  sendResponse(res, {
    success: true,
    statusCode: httpStatus8.CREATED,
    message: "Checkout session created successfully!!",
    data: result
  });
});
var confirmPayment = catchAsync(async (req, res, next) => {
  const signature = req.headers["stripe-signature"];
  if (!signature || Array.isArray(signature)) {
    throw new Error("Missing or invalid Stripe signature.");
  }
  const result = await paymentServices.confirmPaymentIntoDB(req.body, signature);
  sendResponse(res, {
    success: true,
    statusCode: httpStatus8.OK,
    message: "Stripe webhook received successfully!!",
    data: result
  });
});
var getMyPayments = catchAsync(async (req, res, next) => {
  const tenantId = req.user?.id;
  if (!tenantId) {
    throw new Error("Tenant id not found.");
  }
  const allPayments = await paymentServices.getMyPaymentsFromDB(tenantId);
  const message = allPayments.length > 0 ? "Payment history retrieved successfully." : "No payment record found";
  sendResponse(res, {
    success: true,
    statusCode: httpStatus8.OK,
    message,
    data: allPayments
  });
});
var getPaymentById = catchAsync(async (req, res, next) => {
  const paymentId = req.params.id;
  const tenantId = req.user?.id;
  if (!tenantId) {
    throw new Error("Tenant id not found.");
  }
  if (!paymentId) {
    throw new Error("Payment id is required in params.");
  }
  const result = await paymentServices.getPaymentByIdFromDB(paymentId, tenantId);
  sendResponse(res, {
    success: true,
    statusCode: httpStatus8.OK,
    message: "Payment details retrived successfully!!",
    data: result
  });
});
var paymentController = {
  createPayment,
  confirmPayment,
  getMyPayments,
  getPaymentById
};

// src/modules/payment/payment.route.ts
var router7 = Router7();
router7.post("/create", auth(Role.TENANT), paymentController.createPayment);
router7.post("/confirm", paymentController.confirmPayment);
router7.get("/", auth(Role.TENANT), paymentController.getMyPayments);
router7.get("/:id", auth(Role.TENANT), paymentController.getPaymentById);
var paymentRoutes = router7;

// src/middleware/notFound.ts
var notFound = (req, res) => {
  res.status(404).json({
    success: false,
    message: "Route not found.",
    errorDetails: `The requested route ${req.originalUrl} does not exist`
  });
};

// src/middleware/globalErrorHandler.ts
import httpStatus9 from "http-status";
var globalErrorHandler = (error, req, res, next) => {
  console.log("Error: ", error);
  let statusCode;
  let errorMessage = error.message || "Internal server error!";
  if (error instanceof prismaNamespace_exports.PrismaClientValidationError) {
    statusCode = httpStatus9.BAD_REQUEST, errorMessage = "You have provided incorrect field type or missing fields.";
  } else if (error instanceof prismaNamespace_exports.PrismaClientKnownRequestError) {
    if (error.code === "P2002") {
      statusCode = httpStatus9.BAD_REQUEST;
      errorMessage = "Duplicate Key Error.";
    } else if (error.code === "P2003") {
      statusCode = httpStatus9.BAD_REQUEST;
      errorMessage = "Foreign key constraint failed.";
    } else if (error.code === "P2025") {
      statusCode = httpStatus9.BAD_REQUEST;
      errorMessage = "An operation failed because it depends on one or more records that were required but not found.";
    } else if (error.code === "P2028") {
      statusCode = httpStatus9.INTERNAL_SERVER_ERROR;
      errorMessage = "A database transaction failed..";
    }
  } else if (error instanceof prismaNamespace_exports.PrismaClientInitializationError) {
    if (error.errorCode === "P1000") {
      statusCode = httpStatus9.UNAUTHORIZED;
      errorMessage = "Authentication failed against database server. Please check your credentails.";
    } else if (error.errorCode === "P1001") {
      statusCode = httpStatus9.BAD_REQUEST;
      errorMessage = "Can't reach database server.";
    }
  } else if (error instanceof prismaNamespace_exports.PrismaClientUnknownRequestError) {
    statusCode = httpStatus9.INTERNAL_SERVER_ERROR, errorMessage = "Error occurred during query execution.";
  }
  res.status(statusCode || httpStatus9.INTERNAL_SERVER_ERROR).json({
    success: false,
    message: errorMessage,
    errorDetails: error
  });
};

// src/modules/review/review.route.ts
import { Router as Router8 } from "express";

// src/modules/review/review.controller.ts
import httpStatus10 from "http-status";

// src/modules/review/review.service.ts
var createReviewIntoDB = async (payload) => {
  const { propertyId, tenantId } = payload;
  const isPropertyExist = await prisma.property.findUnique({
    where: {
      id: propertyId
    }
  });
  if (!isPropertyExist) {
    throw new Error(
      "You can't create review because this property does not exist."
    );
  }
  const rentalRequest = await prisma.rentalRequest.findFirst({
    where: {
      propertyId,
      tenantId
    }
  });
  if (!rentalRequest) {
    throw new Error(
      "You are not the tenant of that property so you can't create review."
    );
  }
  if (rentalRequest.status !== "COMPLETED") {
    throw new Error("Your rental request status is not COMPLETED.");
  }
  const createdReview = await prisma.review.create({
    data: {
      ...payload
    }
  });
  return createdReview;
};
var reviewServices = {
  createReviewIntoDB
};

// src/modules/review/review.controller.ts
var createReview = catchAsync(async (req, res, next) => {
  const tenantId = req.user?.id;
  const { propertyId, rating, comment } = req.body;
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  if (!tenantId) {
    throw new Error("Tenant id is not found");
  }
  if (!propertyId || !rating) {
    throw new Error("Property id and rating are required");
  }
  if (typeof propertyId !== "string" || !uuidRegex.test(propertyId)) {
    throw new Error("Property id must be a string and should be given in a valid format");
  }
  if (!Number.isInteger(rating) || rating < 1 || rating > 5) {
    throw new Error("Rating should be an integer and rating number must be between 1 and 5");
  }
  if (comment && typeof comment !== "string") {
    throw new Error("Comment must be a string");
  }
  const reviewPayload = {
    propertyId,
    rating,
    comment,
    tenantId
  };
  const result = await reviewServices.createReviewIntoDB(reviewPayload);
  sendResponse(res, {
    success: true,
    statusCode: httpStatus10.CREATED,
    message: "Review created successfully!!",
    data: result
  });
});
var reviewController = {
  createReview
};

// src/modules/review/review.route.ts
var router8 = Router8();
router8.post("/", auth(Role.TENANT), reviewController.createReview);
var reviewRoutes = router8;

